<template><view class="shell"><TopBar tag="朋友请客"/><view v-if="error" class="error">{{error}}<button class="link" @click="load">重新看看</button></view><template v-if="invite"><view class="eyebrow">{{avatarSymbols[invite.senderAvatar] || '♧'}} {{invite.senderName}} 给你留了一份</view><view class="title">这份心意，<text class="line-break"> </text><text class="highlight">请你收下。</text></view><ItemArt :habit="invite.habit"/><view class="row"><text class="small-title">{{invite.item}}</text><text class="badge">虚构 ¥{{money(invite.amount)}}</text></view><view class="body" style="margin-top:20px">{{invite.reason}}</view><button v-if="invite.status==='pending'" class="primary" :disabled="busy" @click="claim">{{busy?'正在收下…':'收下这一份 ↗'}}</button><button v-else-if="invite.status==='claimed'" class="secondary" :disabled="busy" @click="claim">已被收下 · 如果是你，查看小票</button><view v-else class="card" style="margin-top:24px">{{invite.status==='expired'?'这份请客已经过期了。':'这份请客已经撤销了。'}}</view><view class="footer">一张卡，只请一位朋友。<text class="line-break"> </text>不需要付款或回请，不会自动增加你的转存记录。<text class="line-break"> </text>点击收下将建立账号，留下这件共同的小事。</view><button class="link" @click="home">自己去小店逛逛 →</button></template></view></template>
<script setup>
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import TopBar from '../../components/jdml/TopBar.vue';import ItemArt from '../../components/jdml/ItemArt.vue';import {api,go,home,money,notify} from '../../services/api';const avatarSymbols={leaf:'♧',star:'✧',cup:'☕',cloud:'☁'};const invite=ref(null),error=ref(''),busy=ref(false);let token='';onLoad(q=>{token=q.token || '';load();});async function load(){error.value='';try{invite.value=await api('preview',{token});}catch(e){error.value=e.message;}}async function claim(){if(busy.value)return;busy.value=true;try{const e=await api('claim',{token});uni.redirectTo({url:'/pages/receipt/receipt?id='+e.id});}catch(e){notify(e);await load();}finally{busy.value=false;}}
</script>
